{
  "findings": [
    {
      "check_id": "CKV_K8S_38",
      "title": "Service account token automount is not disabled",
      "resource": "kubernetes_service_account_v1.pass",
      "severity": "MEDIUM",
      "explanation": "The service account does not explicitly disable automatic API token mounting, so pods using it may receive Kubernetes API credentials even when they do not require them."
    }
  ],
  "patched_code": "resource \"kubernetes_service_account_v1\" \"pass\" {\n  metadata {\n    name      = \"terraform-example\"\n    namespace = \"brian\"\n  }\n\n  automount_service_account_token = false\n\n  secret {\n    name = \"${kubernetes_secret_v1.example.metadata.0.name}\"\n  }\n}\n",
  "fix_summary": "Disabled automatic service account token mounting to prevent unnecessary Kubernetes API credential exposure. Existing declarations and the explicitly configured secret reference were preserved."
}
